  function legendTerrainHint(t,x,y){
    const dungeon=state?.artifactDungeon46;
    const entry=state?.artifactPortal46,exit=state?.artifactExit46;
    if(t===TT.PORTAL&&entry?.x===x&&entry?.y===y)return `목적지는 '${entry.name||'전설무기 던전'}'이다. 던전에서 귀환하면 이 일회성 입구는 닫힌다.`;
    if(!dungeon)return'';
    if(t===TT.PORTAL&&exit?.x===x&&exit?.y===y)return '이 귀환문을 밟으면 원래 만루 층으로 돌아간다. 현재 전설던전은 닫히며 이 입구로 다시 들어올 수 없다.';
    if(t===TT.LOCKED_GATE){
      const door=(state?.keyPlan96?.doors||[]).find(d=>d.x===x&&d.y===y&&d.open!==true);
      if(door?.keyId==='iron')return '철제 열쇠가 필요한 별전 봉인문이다. 먼저 이 별전을 열어 청옥열쇠로 이어지는 길을 확보해야 한다.';
      if(door?.keyId==='jade')return '청옥열쇠가 필요한 마지막 봉인문이다. 너머 성소에 이 전설던전의 무기가 놓여 있다.';
    }
    if(t===TT.KEY_TILE){
      const keyInfo=(state?.keyPlan96?.keys||[]).find(q=>q.x===x&&q.y===y&&q.active!==false);
      if(keyInfo?.keyId==='iron')return '철제 열쇠다. 먼저 철문으로 봉인된 별전을 열어 청옥열쇠를 찾아야 한다.';
      if(keyInfo?.keyId==='jade')return '청옥열쇠다. 전설무기 성소를 막는 청옥문을 여는 마지막 열쇠다.';
    }
    if(t>=500&&t<660&&(t-500)%16===7)return '전설던전 전용 교량이다. 물·용암·공허를 가로지를 때는 이 통로를 벗어나지 않는 편이 안전하다.';
    if(t===TT.LAVA)return '전설던전의 실제 위험지형이다. 장식용 균열이 아니며, 화염·용암 대책이 없다면 직접 밟지 않는 편이 좋다.';
    return'';
  }
