function branchGridPack(grid){const h=grid.length,w=grid[0]?.length||0,r=[];for(const row of grid)for(const v of row){if(r.length&&r[r.length-2]===v)r[r.length-1]++;else r.push(v,1);}return{w,h,r}}
function branchGridUnpack(p){if(!p||!Number.isInteger(p.w)||!Number.isInteger(p.h)||p.w<1||p.h<1||p.w*p.h>100000||!Array.isArray(p.r)||p.r.length%2)throw Error('Invalid branch grid encoding');const a=[];for(let i=0;i<p.r.length;i+=2){const n=p.r[i+1];if(!Number.isInteger(n)||n<1||a.length+n>p.w*p.h)throw Error('Invalid branch grid run');for(let j=0;j<n;j++)a.push(p.r[i]);}if(a.length!==p.w*p.h)throw Error('Truncated branch grid');return Array.from({length:p.h},(_,y)=>a.slice(y*p.w,(y+1)*p.w))}
